#include <stdio.h>
#include <string.h>
#include <ctype.h>

int main(int argc, char *argv[])
{
    if (argc < 2) {
        puts("INVALID");
        return 0;
    }
    const char *s = argv[1];
    if (strlen(s) != 10) {
        puts("INVALID");
        return 0;
    }
    if (!isdigit((unsigned char)s[0]) || !isdigit((unsigned char)s[1]) || s[2] != '-' ||
        !isdigit((unsigned char)s[3]) || !isdigit((unsigned char)s[4]) || s[5] != '-' ||
        !isdigit((unsigned char)s[6]) || !isdigit((unsigned char)s[7]) ||
        !isdigit((unsigned char)s[8]) || !isdigit((unsigned char)s[9])) {
        puts("INVALID");
        return 0;
    }
    int day, month, year;
    if (sscanf(s, "%2d-%2d-%4d", &day, &month, &year) != 3) {
        puts("INVALID");
        return 0;
    }
    if (year < 1) {
        puts("INVALID");
        return 0;
    }
    if (month < 1 || month > 12) {
        puts("INVALID");
        return 0;
    }
    int dim[12] = {31,28,31,30,31,30,31,31,30,31,30,31};
    if ((year % 4 == 0 && year % 100 != 0) || (year % 400 == 0)) {
        dim[1] = 29;
    }
    if (day < 1 || day > dim[month-1]) {
        puts("INVALID");
        return 0;
    }
    puts("VALID");
    return 0;
}
